import io
import os
import sqlite3
from sync.client import VendorClient, DEFAULT_BASE_URL
records = list(VendorClient(os.environ.get('VENDOR_API', DEFAULT_BASE_URL), notices=io.StringIO()).iter_items())
with sqlite3.connect('data/catalog.db') as db, sqlite3.connect(os.environ['CATALOG_BACKUP']) as backup:
    before = {r[0]: r for r in backup.execute('SELECT * FROM products')}
    after = {r[0]: r for r in db.execute('SELECT * FROM products')}
    seen = {r['sku'] for r in records}
    for sku, row in before.items():
        if row[3] == 'manual' or sku not in seen:
            assert after[sku] == row, sku
    for record in records:
        sku = record['sku']
        if sku in before and before[sku][3] == 'manual':
            continue
        if record.get('deleted'):
            assert sku not in after, sku
        else:
            row = after[sku]
            assert row[1:4] == (record['name'], record['price_paise'], 'vendor'), sku
            if record.get('updated_at'):
                assert row[4] == record['updated_at'], sku
    assert set(after) == (set(before) | {r['sku'] for r in records if not r.get('deleted')}) - {r['sku'] for r in records if r.get('deleted') and r['sku'] in before and before[r['sku']][3] == 'vendor'}
    assert db.execute('PRAGMA integrity_check').fetchone() == ('ok',)
    print('Verified every live record and tombstone; all manual and unmentioned rows preserved.')
    print('Sync state:', db.execute('SELECT * FROM sync_state ORDER BY key').fetchall())
